import React from 'react';
import './Settings.css';

const Settings = () => {
  return (
    <div className="settings-container">
      <h1>Settings</h1>
      <div className="settings-menu">
        <button className="settings-button">Profile</button>
        <button className="settings-button">Notifications</button>
        <button className="settings-button">Shipping & Returns</button>
        <button className="settings-button logout-button">Logout</button>
      </div>
    </div>
  );
};

export default Settings;
